import * as THREE from 'three';

export interface TextureLoaderLike {
  loadAsync(url: string): Promise<THREE.Texture>;
}

export interface AssetLoadProgress {
  completed: number;
  total: number;
  ratio: number;
  currentKey?: string;
}

export interface TextureRequest {
  key: string;
  url: string;
  optional?: boolean;
}

export interface TextureLoadResult {
  key: string;
  texture: THREE.Texture;
  fallback: boolean;
  error?: unknown;
}

export type AssetProgressListener = (progress: AssetLoadProgress) => void;

function createFallbackTexture(): THREE.DataTexture {
  const data = new Uint8Array([
    255, 0, 255, 255,
    30, 30, 30, 255,
    30, 30, 30, 255,
    255, 0, 255, 255,
  ]);
  const texture = new THREE.DataTexture(data, 2, 2, THREE.RGBAFormat);
  texture.needsUpdate = true;
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  texture.name = 'fallback-texture';
  return texture;
}

export class AssetManager {
  private readonly textures = new Map<string, THREE.Texture>();
  private readonly fallbackTexture: THREE.Texture;

  constructor(
    private readonly textureLoader: TextureLoaderLike = new THREE.TextureLoader(),
    fallbackTexture: THREE.Texture = createFallbackTexture(),
  ) {
    this.fallbackTexture = fallbackTexture;
  }

  getTexture(key: string): THREE.Texture | undefined {
    return this.textures.get(key);
  }

  hasTexture(key: string): boolean {
    return this.textures.has(key);
  }

  async loadTexture(request: TextureRequest): Promise<TextureLoadResult> {
    try {
      const texture = await this.textureLoader.loadAsync(request.url);
      texture.name ||= request.key;
      this.textures.set(request.key, texture);
      return { key: request.key, texture, fallback: false };
    } catch (error) {
      if (request.optional === false) throw error;
      this.textures.set(request.key, this.fallbackTexture);
      return { key: request.key, texture: this.fallbackTexture, fallback: true, error };
    }
  }

  async loadTextures(
    requests: readonly TextureRequest[],
    onProgress?: AssetProgressListener,
  ): Promise<readonly TextureLoadResult[]> {
    const total = requests.length;
    if (total === 0) {
      onProgress?.({ completed: 0, total: 0, ratio: 1 });
      return [];
    }

    let completed = 0;
    const results: TextureLoadResult[] = [];
    onProgress?.({ completed, total, ratio: 0 });

    for (const request of requests) {
      const result = await this.loadTexture(request);
      results.push(result);
      completed += 1;
      onProgress?.({ completed, total, ratio: completed / total, currentKey: request.key });
    }

    return results;
  }

  dispose(): void {
    const disposed = new Set<THREE.Texture>();
    for (const texture of this.textures.values()) {
      if (!disposed.has(texture)) {
        texture.dispose();
        disposed.add(texture);
      }
    }
    if (!disposed.has(this.fallbackTexture)) this.fallbackTexture.dispose();
    this.textures.clear();
  }
}
